begin;

-- Revocable event-scoped machine credentials. The raw bearer token is never
-- stored, only a SHA-256 digest generated by the application.
create table if not exists integration_credentials (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references events(id) on delete cascade,
  label text not null,
  token_hash text not null unique,
  scopes text[] not null default array['state:read', 'live:control']::text[],
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);
create index if not exists integration_credentials_event_created_idx on integration_credentials(event_id, created_at desc);
alter table integration_credentials enable row level security;
commit;
